    h, w = len(grid), len(grid[0])

    sep_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_row is not None:
        panels = [grid[:sep_row], grid[sep_row + 1:]]
    else:
        sep_col = next(c for c in range(w)
                       if all(grid[r][c] == grid[0][c] for r in range(h)))
        panels = [[row[:sep_col] for row in grid],
                  [row[sep_col + 1:] for row in grid]]

    # The panel with the smaller, sparse set of non-background marks is the
    # pattern to convert.
    def pattern_panel(panel):
        from collections import Counter
        counts = Counter(x for row in panel for x in row)
        return len(counts) > 1 and min(counts.values()) < max(counts.values())

    panel = next((p for p in panels if pattern_panel(p)), panels[0])
    from collections import Counter
    bg = Counter(x for row in panel for x in row).most_common(1)[0][0]
    return [[3 if x != bg else bg for x in row] for row in panel]
